<script setup lang="ts">
import {ref,computed} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {runTool} from '../../../../../packages/lottery-core/tools';import type {ToolConfig} from '../../../../../packages/lottery-core/tools';import {remember,pin,labels} from '../../services/tasks';
const config=ref<ToolConfig>({mode:'wheel',name:'',items:[],count:1,min:1,max:100,rows:2,cols:3,unique:true}),text=ref(''),result=ref<string[][]>([]),error=ref(''),busy=ref(false),excluded=ref<number[]>([]),exclude=ref(false);
const listMode=computed(()=>!['number','dice','coin'].includes(config.value.mode));
onLoad(q=>{const mode=String(q?.mode||'wheel');if(!labels[mode]){error.value='未知工具';return}const saved=q?.resume?uni.getStorageSync('lastTool')?.config:uni.getStorageSync('tool-'+mode);config.value={...config.value,count:mode==='group'?2:1,...saved,mode:mode as ToolConfig['mode']};const preset=uni.getStorageSync('pendingTool');if(preset){config.value=preset;uni.removeStorageSync('pendingTool')}text.value=config.value.items.join('\n');uni.setNavigationBarTitle({title:labels[config.value.mode]})});
function read():ToolConfig{return {...config.value,items:text.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),count:Number(config.value.count),min:Number(config.value.min),max:Number(config.value.max),rows:Number(config.value.rows),cols:Number(config.value.cols)}}
async function start(){if(busy.value)return;error.value='';try{const c=read();if(listMode.value&&!c.items.length)throw Error('请先输入选项或名单');const pool=c.items.map((name,index)=>({name,index})).filter(x=>!excluded.value.includes(x.index));const selected=runTool({...c,items:pool.map(x=>String(x.index))});const output=listMode.value?selected.map(g=>g.map(x=>x==='空座'?x:c.items[Number(x)])):selected;busy.value=true;remember(c);if(c.mode==='wheel')await new Promise(r=>setTimeout(r,800));result.value=output;if(c.mode==='draw'&&exclude.value)excluded.value.push(...selected.flat().map(Number));}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function fixed(){try{pin(read());uni.showToast({title:'已固定到我的名单'})}catch(e){error.value=(e as Error).message}}
function reset(){excluded.value=[];result.value=[];error.value=''}
</script>
<template><view class="page"><view class="card"><view class="title">{{labels[config.mode]}}</view><input v-model="config.name" placeholder="名称（可不填）" maxlength="100"/><template v-if="listMode"><view class="muted">选项 / 名单（每行一个）</view><textarea v-model="text" maxlength="15000" @input="reset"/></template>
<template v-if="['group','draw','number','dice'].includes(config.mode)"><view class="muted">{{config.mode==='group'?'分组数':config.mode==='dice'?'骰子数量（1–3颗）':'生成数量'}}</view><input v-model="config.count" type="number"/></template>
<template v-if="config.mode==='number'"><view class="muted">最小值 / 最大值</view><view class="row"><input v-model="config.min" type="number"/><input v-model="config.max" type="number"/></view><view @click="config.unique=!config.unique">{{config.unique?'☑':'□'}} 不重复</view></template>
<view v-if="config.mode==='draw'" @click="exclude=!exclude;reset()">{{exclude?'☑':'□'}} 抽中后排除 <text class="muted">已排除 {{excluded.length}} 人</text></view>
<template v-if="config.mode==='seat'"><view class="muted">排数 / 每排座位数</view><view class="row"><input v-model="config.rows" type="number"/><input v-model="config.cols" type="number"/></view></template>
</view><view v-if="busy" class="wheel">正在选择…</view><button :disabled="busy" @click="start">{{result.length?'再来一次':'开始'}}</button><view class="error">{{error}}</view>
<view v-for="(group,i) in result" :key="i" class="card"><view v-if="['group','pair','seat'].includes(config.mode)" class="muted">{{config.mode==='seat'?'第'+(i+1)+'排':config.mode==='pair'&&group.length===1?'轮空':'第'+(i+1)+'组'}}</view><view class="result">{{group.join('、')}}</view></view>
<view v-if="result.length" class="row"><button @click="fixed">固定这份配置</button><button @click="reset">重置排除与结果</button></view><view class="muted">临时随机自动记忆，不需要登录。名单与配置保存在当前设备。</view></view></template>
<style scoped>.title{font-size:24px;font-weight:800}.row{display:flex;gap:10px}.row>*{flex:1}.row button{font-size:13px}.result{font-size:25px;font-weight:700;margin-top:8px}.error{color:#a23036}.wheel{width:180px;height:180px;border:12px solid #eae7ff;border-top-color:#6657e8;border-radius:50%;margin:24px auto;display:flex;align-items:center;justify-content:center;color:#6657e8}</style>
